head.script:
scwin.onpageload = function() {
	// 대륙별 3개 나라 × 품목 3개를 2번씩, 전체를 다시 2번 = 108 Row
	var CONT = [["Asia", ["Korea", "China", "Japan"]], ["Europe", ["Germany", "France", "Denmark"]], ["Americas", ["Canada", "USA", "Mexico"]]];
	var QTY = { "TV": "823", "Freezer": "288", "Washer": "325" };
	var json = [];
	for (var r = 0; r < 2; r++) {
		CONT.forEach(function(ct) {
			for (var k = 0; k < 2; k++) {
				ct[1].forEach(function(c) {
					["TV", "Freezer", "Washer"].forEach(function(it) {
						json.push({ "col1": ct[0], "col2": c, "col3": it, "col4": (c == "Korea" || c == "China") ? "400" : QTY[it] });
					});
				});
			}
		});
	}
	dataList1.setJSON(json);
};
scwin.gridView1_ongroupby = function(options) {
	options.groupbyHeader = [{ inputType: 'expression', expression: 'toggle() + depthStr() + "    [ " + count() + " Cases ]  "', align: 'left', colSpan:4 }];
	options.closeGroup = true;
	options.groupbyFooter = {
		depth_0 : [ {colSpan:3, value: "(1) Maximum Value", align: "right"}, { inputType: 'expression', expression:'MAX("col4")'} ],
		depth_1: [ {colSpan:3, value: "(2) Maximum Value", align: "right"}, { inputType: 'expression', expression:'MAX("col4")'} ],
		depth_2: [ {colSpan:3, value: "(3) Maximum Value", align: "right"}, { inputType: 'expression', expression:'MAX("col4")'} ]
	};
	gridView1.groupby(options);
};
